MEDIANE(A1:G1)`. المتوسط: `=MOYENNE(A1:G1)`. المنوال: `=MODE(A1:G1)`"], ["اقترح سلسلة تكرارها الكلي 7 ومتوسطها 7.", "مثلا 7 7 7 7 7 7 7. المجموع 49 و`49/7=7`. أو 5 و6 و7 و7 و7 و8 و9 فالمجموع 49 أيضا"]]}, {"n": 61, "m": 9, "i": "🔺", "t": "خاصية طالس", "B": [["النص", ["(BM) و(CN) مستقيمان متقاطعان في A", "إذا كان (MN) // (BC) فإن `AM/AB=AN/AC=MN/BC`"]], ["نتيجة", ["أطوال أضلاع المثلث AMN متناسبة مع أطوال أضلاع المثلث ABC", "جدول التناسبية: AM/AB وAN/AC وMN/BC"]], ["الحالتان", ["الحالة الأولى: M بين A وB (مثلث صغير داخل الكبير)", "الحالة الثانية: A بين M وB (مثلثان متقابلان بالرأس)"]], ["تذكير", ["أقرأ النسب بنفس الترتيب: ما يتعلق بالرأس A في البسط", "طالس يحتاج مستقيمين متقاطعين ومستقيمين متوازيين"]]], "K": "إذا كان (MN)//(BC) فإن AM/AB = AN/AC = MN/BC.", "M": ["أتأكد من وجود التوازي", "أكتب النسب الثلاث بنفس الترتيب", "أستعمل نسبتين فقط لحل المجهول"], "X": "المثلث الصغير هو تكبير أو تصغير للمثلث الكبير، فأضلاعه متناسبة مع أضلاعه.", "EX": [["(IJ)//(BC) مع AB=6 وAC=7 وAB'=3,2 (B' على AB). احسب AC'.", "بتطبيق طالس: `AB'/AB=AC'/AC`. `3,2/6=AC'/7`. `AC'=7×3,2/6=56/15≈3,73` سم"], ["AB=3,2 وAC=4,5 وBC=3 وAB'=1,6. احسب AC' وB'C'.", "`AB'/AB=1,6/3,2=0,5`. `AC'=0,5×4,5=2,25`. `B'C'=0,5×3=1,5`"]]}, {"n": 62, "m": 9, "i": "🔍", "t": "معامل التناسبية والتكبير والتصغير", "B": [["المعامل k", ["المثلثان AMN وABC في وضعية طالس", "جدول التناسبية: AM/AB وAN/AC وMN/BC كلها تساوي k", "k عدد موجب تماما"]], ["العلاقات", ["`AM=k×AB` و`AN=k×AC` و`MN=k×BC`"]], ["تصغير", ["`k<1`: المثلث AMN تصغير للمثلث ABC", "k معامل التصغير"]], ["تكبير", ["`k>1`: المثلث AMN تكبير للمثلث ABC", "k معامل التكبير"]]], "K": "اقسم طولا في المثلث الأول على طوله المقابل في الثاني لتحصل على k.", "M": ["أحدد المثلثين وأضلاعهما المتقابلة", "أحسب k من نسبة معروفة", "أستعمل k لحساب بقية الأضلاع"], "X": "كلما عرفنا نسبة واحدة (مثلا 1/3) عرفنا كل الأضلاع الأخرى بضربها في هذه النسبة.", "EX": [["إذا كان `AM/AB=1/3` وAB=12 وBC=9 فاحسب AM وMN.", "`k=1/3`. `AM=12×1/3=4`. `MN=9×1/3=3`. المثلث AMN تصغير بمعامل 1/3"], ["ABC مثلث AB=4 وAC=5 وBC=6. M∈[AB] مع AM=1 و(MN)//(BC) حيث N∈[AC]. احسب AN وMN.", "`k=AM/AB=1/4`. `AN=k×AC=5/4=1,25`. `MN=k×BC=6/4=1,5`. المثلث AMN تصغير بمعامل 1/4"]]}, {"n": 63, "m": 9, "i": "📏", "t": "حساب أطوال بطالس", "B": [["الخطوات", ["أحدد المستقيمين المتوازيين والمتقاطعين", "أسمّي المثلثين في وضعية طالس", "أكتب النسب المتساوية", "أحتفظ بالمساواة التي فيها المجهول وأحلها"]], ["مثال: متوازي أضلاع", ["`ABCD` متوازي أضلاع و`AB=5` و`BC=3`", "M على [AD] مع `AM=2`، و(BM) يقطع (DC) في N", "`AD=3` فـ `MD=1`"]], ["المثلثان", ["MAB وMDN في وضعية طالس لأن (AB)//(DN)", "`MA/MD=MB/MN=AB/DN`", "`2/1=5/DN`"]], ["النتيجة", ["`DN=5/2=2,5` سم"]]], "K": "حدّد وضعية طالس، اكتب النسب، واحتفظ بالنسبتين اللتين تتضمنان المعلوم والمجهول.", "M": ["أرسم شكلا واضحا", "أتحقق من ترتيب الأضلاع المتقابلة", "أحل بالضرب التبادلي"], "X": "التوازي يعطينا مثلثين متناسبين. نكتب تساوي نسبتين وفيهما المجهول فنحلها كمعادلة بسيطة.", "EX": [["ABCD متوازي أضلاع AB=5 وBC=3 وM∈[AD] مع AM=2. (BM) يقطع (DC) في N. احسب DN.", "(AB)//(CD) فـ (AB)//(DN) والمثلثان MAB وMDN في وضعية طالس. `MA/MD=AB/DN`. `MD=AD-AM=3-2=1`. `2/1=5/DN`. `DN=5/2=2,5` سم"], ["BEM مثلث BM=9 وBE=12 وEM=6. K∈[BE] مع EK=4. المستقيم المار من K الموازي لـ(EM) يقطع (BM) في L. احسب محيط BKL.", "`BK=12-4=8`. `BK/BE=BL/BM=KL/EM=8/12=2/3`. `BL=9×2/3=6` و`KL=6×2/3=4`. المحيط `8+6+4=18` سم"]]}, {"n": 64, "m": 9, "i": "🔄", "t": "الخاصية العكسية لطالس", "B": [["النص", ["(d) و(d') مستقيمان متقاطعان في A", "B وB' من (d) وC وC' من (d') ومختلفة عن A", "إذا كان `AB'/AB=AC'/AC` والنقاط A وB وB' وA وC وC' مرتبة بنفس الترتيب فإن (BC)//(B'C')"]], ["شرط الترتيب", ["النقاط على المستقيمين تكون بنفس الترتيب", "وإلا فلا نستطيع الاستنتاج", "بل (BC) و(B'C') غير متوازيين"]], ["مثال", ["`ON/OP=5/4=1,25` و`OM/OR=3/2,4=1,25`", "النقاط M وO وR وN وO وP بنفس الترتيب", "إذن (MN)//(PR)"]], ["الاستعمال", ["إثبات التوازي", "نحسب نسبتين ونقارنهما"]]], "K": "إذا تساوت النسبتان والنقاط بنفس الترتيب فالمستقيمان متوازيان.", "M": ["أحسب النسبتين وأقارنهما", "أتحقق من ترتيب النقاط", "أكتب الجواب بعبارة «حسب الخاصية العكسية لطالس»"], "X": "طالس يقول: التوازي يعطي تساوي النسب. وعكسه يقول: تساوي النسب مع نفس الترتيب يعطي التوازي.", "EX": [["في الشكل: OM=3 وOR=2,4 وON=5 وOP=4 وM وO وR على استقامة واحدة وN وO وP أيضا بنفس الترتيب. هل (MN)//(PR)؟", "`OM/OR=3/2,4=1,25` و`ON/OP=5/4=1,25`. النسبتان متساويتان والنقاط بنفس الترتيب. حسب الخاصية العكسية لطالس (MN)//(PR)"], ["لماذا لا نستنتج التوازي إذا كانت النقاط بترتيب مختلف رغم تساوي النسبتين؟", "الخاصية تشترط الترتيب نفسه على المستقيمين. إذا كان B' على جهة A وC' على الجهة الأخرى فالمستقيمان غير متوازيين مهما كانت النسبتان"]]}, {"n": 65, "m": 9, "i": "✅", "t": "إثبات التوازي أو عدمه", "B": [["الطريقة", ["أكتب النسبتين المناسبتين", "أقارنهما بالضرب التبادلي", "أتحقق من الترتيب"]], ["حالة التوازي", ["`DA/DF=3,5/1,5` و`DB/DC=4,2/1,8`", "`3,5×1,8=6,3` و`1,5×4,2=6,3`", "إذن (CF)//(AB) بالعكسية"]], ["حالة عدم التوازي", ["`AB/AE=3,2/4,6` و`AD/AF=3,5/5`", "`3,2×5=16` و`4,6×3,5=16,1`", "النسبتان مختلفتان فالمستقيمان غير متوازيين"]], ["لماذا؟", ["لو كان التوازي صحيحا لكانت النسبتان متساويتين حسب طالس", "وبما أنهما مختلفتان فالتوازي غير صحيح"]]], "K": "تساوي النسبتين مع الترتيب يعني التوازي؛ واختلافهما يعني عدم التوازي (بطالس المباشرة).", "M": ["أستعمل الضرب التبادلي لمقارنة نسبتين", "أتحقق أن النقاط على استقامة واحدة", "أنقل الشكل بوضوح"], "X": "إذا تساوت النسبتان فالتوازي صحيح، وإن اختلفتا فهو غير صحيح. نقارن النسب بالضرب في الأطراف.", "EX": [["AB=3,2 وAD=3,5 وDC=1,8 وDF=1,5 وBD=4,2 وAE=4,6. هل (AB)//(CF)؟ وهل (BD)//(EF)؟", "النقاط F وD وA على استقامة وC وD وB. `DA/DF=3,5/1,5` و`DB/DC=4,2/1,8`. `3,5×1,8=6,3` و`1,5×4,2=6,3` فالنسبتان متساويتان وبنفس الترتيب. (CF)//(AB). أما `AB/AE=3,2/4,6` و`AD/AF=3,5/5`: `3,2×5=16` و`4,6×3,5=16,1`. النسبتان مختلفتان. فالمستقيمان (BD) و(EF) غير متوازيين"], ["أحد التلميذين: `OM/OA=9/5,4≈1,7` و`ON/OP=5/3≈1,7` بترتيب النقاط نفسه. ماذا يستنتج؟", "النسبتان متساويتان تقريبا (`9/5,4=5/3`): `9×3=27` و`5,4×5=27`. إذن (MN)//(AP) بالخاصية العكسية"]]}, {"n": 66, "m": 9, "i": "✏️", "t": "إنشاءات بخاصية طالس", "B": [["قطعة بطول معلوم", ["مثال: `AB=14/3`", "نكتب `3×AB=7×2` أي `3/7=2/AB`", "نرسم نصفي مستقيمين (Ax) و(Ay)، `AC=3` و`AD=7` على (Ax) و`AE=2` على (Ay)", "المستقيم الموازي لـ(CE) المار من D يقطع (Ay) في B"]], ["نقطة تقسم قطعة بنسبة", ["لإنشاء M على [AB] حيث `MA/MB=3/2`", "نرسم (d₁) و(d₂) متوازيين مارين من A وB", "نأخذ `AK=AF=3` و`BE=2`", "(EF) يقطع (AB) في M"]], ["تقسيم قطعة إلى 3 أجزاء", ["بالمثلثات المتناسبة نبيّن `BM=MN=NA=BA/3`"]], ["الأدوات", ["مسطرة غير مدرّجة ومدور", "التوازي يعوّض التدريج"]]], "K": "ارسم مستقيمين متوازيين ثم عيّن النقاط بوحدات متساوية فتتحقق النسبة المطلوبة.", "M": ["أحدد النسبة المطلوبة", "أرسم متوازيين وأختار وحدة", "أطبق طالس لإثبات صحة الإنشاء"], "X": "التوازي يحفظ النسب. لذلك نقيس على مستقيم مساعد بالتدريج الذي نريده ثم ننقل النسبة إلى القطعة المطلوبة.", "EX": [["أنشئ قطعة [AB] بحيث `AB=14/3` باستعمال مسطرة غير مدرجة.", "`3×AB=7×2` فـ `3/7=2/AB`. نرسم (Ax) و(Ay)، `C` و`D` على (Ax) حيث `AC=3` و`AD=7`، و`E` على (Ay) حيث `AE=2`. نرسم من D الموازي لـ(CE) فيقطع (Ay) في B. طالس: `AC/AD=AE/AB` فـ `AB=7×2/3=14/3`"], ["كيف تنشئ M على [AB] حيث `MA/MB=3/2`؟", "نرسم (d₁) و(d₂) متوازيين من A وB. نأخذ E على (d₂) حيث BE=2 وK وF على (d₁) حيث AK=AF=3 (من جهتي A). (EF) يقطع (AB) في M. طالس في MAF وMBE: `MA/MB=AF/EB=3/2`"]]}, {"n": 67, "m": 9, "i": "🍦", "t": "وضعية إدماجية: أسطوانة داخل مخروط", "B": [["المعطيات", ["مخروط دوران ارتفاعه 18 سم ونصف قطر قاعدته 6 سم", "أسطوانة مرسومة داخله ارتفاعها `h=r` ونصف قطر قاعدتها r"]], ["رسم المقطع", ["مثلثان يشتركان في رأس المخروط O", "مثلث صغير ارتفاعه `18-h` وقاعدته نصف القطر r", "مثلث كبير ارتفاعه 18 وقاعدته 6"]], ["تطبيق طالس", ["`r/6=(18-r)/18` (لأن `h=r`)", "`18r=108-6r`", "`24r=108` فـ `r=4,5` سم"]], ["الحجم", ["`V=πr²h=πr³`", "`V=π×4,5³=91,125π≈286,3` سم³"]]], "K": "فسّر الشكل بمثلثين في وضعية طالس، حل معادلة لإيجاد r ثم احسب الحجم πr²h.", "M": ["أرسم مقطع المخروط والأسطوانة", "أكتب النسبة بطالس", "أحل المعادلة ثم أحسب الحجم"], "X": "الأسطوانة تلمس سطح المخروط من الأعلى، فنصف قطرها يتناسب مع الارتفاع المتبقي. هذا ما يعطي معادلة r.", "EX": [["جد نصف قطر الأسطوانة r علما أن ارتفاعها h=r.", "طالس: `r/6=(18-h)/18` مع `h=r`. `18r=6(18-r)=108-6r`. `24r=108`. `r=4,5` سم"], ["احسب حجم الأسطوانة.", "`V=πr²h=π×4,5²×4,5=π×91,125≈286,3` سم³"]]}, {"n": 68, "m": 10, "i": "📏", "t": "الجيب وجيب التمام والظل", "B": [["المثلث القائم", ["نختار زاوية حادة x ونسمي الضلع المقابل لها والضلع المجاور لها", "الوتر هو الضلع المقابل للزاوية القائمة"]], ["الجيب", ["`sin x = المقابل ÷ الوتر`"]], ["جيب التمام", ["`cos x = المجاور ÷ الوتر`"]], ["الظل", ["`tan x = المقابل ÷ المجاور`", "sin وcos محصوران بين 0 و1 لأن الوتر أطول ضلع"]]], "K": "sin = مقابل/وتر، cos = مجاور/وتر، tan = مقابل/مجاور.", "M": ["أحدد الزاوية x أولا", "أميز المقابل والمجاور بالنسبة لـ x", "الوتر ثابت لا يتغير"], "X": "النسب المثلثية تربط زاوية حادة بنسبة بين طولين في مثلث قائم؛ تتغير بتغير الزاوية فقط لا بحجم المثلث.", "EX": [["مثلث قائم أضلاعه 3 و4 و5 (الوتر 5). احسب sin وcos وtan للزاوية المقابلة للضلع 3.", "`sin x = 3/5 = 0,6`. `cos x = 4/5 = 0,8`. `tan x = 3/4 = 0,75`"], ["لماذا لا يمكن أن يكون sin x = 1,2؟", "لأن المقابل أصغر من الوتر دائما. إذن `sin x` أقل من 1"]]}, {"n": 69, "m": 10, "i": "🔺", "t": "مثال: مثلث أضلاعه 3 و2 و√13", "B": [["المعطيات", ["مثلث EFG قائم، ضلعاه 3 و2 والوتر `√13`", "الوتر: `3^{2}+2^{2}=13`"]], ["الزاوية E", ["`sin E = 3/√13`", "`cos E = 2/√13`"]], ["الزاوية F", ["`cos F = 3/√13`", "`sin F = 2/√13`"]], ["ملاحظة", ["`sin E = cos F` لأن الزاويتين متتامتان", "`sin E ≈ 0,83`"]]], "K": "في مثلث قائم: جيب إحدى الزاويتين الحادتين يساوي جيب تمام الأخرى.", "M": ["أحسب الوتر بفيثاغورس", "أكتب النسبة ثم أبسط", "أقرّب بالآلة عند الحاجة"], "X": "الزاويتان الحادتان متتامتان، فالمقابل لإحداهما مجاور للأخرى، ولذلك يتبادل sin وcos الدورين.", "EX": [["احسب الوتر في مثلث ضلعاه القائمان 3 و2 ثم sin الزاوية المقابلة للضلع 3 تقريبا.", "`3^{2}+2^{2}=13` فالوتر `√13≈3,606`. `sin = 3/3,606≈0,83`"], ["مثلث قائم أضلاعه 5 و12 و13. احسب cos الزاوية المجاورة للضلع 5.", "`cos = 5/13≈0,38`"]]}, {"n": 70, "m": 10, "i": "🧮", "t": "استعمال الآلة الحاسبة", "B": [["الضبط", ["نضع الآلة على نمط الدرجات (DEG)"]], ["من زاوية إلى نسبة", ["`sin 54° ≈ 0,81`", "`cos 54° ≈ 0,59`", "`tan 54° ≈ 1,38`"]], ["من نسبة إلى زاوية", ["نستعمل `sin^{-1}` أو `cos^{-1}` أو `tan^{-1}`", "`sin^{-1}(0,4) ≈ 24°`"]], ["مثال آخر", ["`tan^{-1}(0,3) ≈ 17°`", "نتحقق: `tan 17° ≈ 0,31`"]]], "K": "نتأكد دائما أن الآلة بنمط الدرجات، ثم نستعمل sin وcos وtan أو معكوساتها.", "M": ["DEG وليس RAD", "أقرّب النتيجة كما يطلب السؤال", "أتحقق بالعملية العكسية"], "X": "الأزرار sin⁻¹ وcos⁻¹ وtan⁻¹ تعطي الزاوية عندما نعرف النسبة.", "EX": [["احسب بالآلة: `sin 25°` و`cos 25°` و`tan 25°` (تقريبا إلى 0,01).", "`sin 25°≈0,42`. `cos 25°≈0,91`. `tan 25°≈0,47`"], ["جد قيس الزاوية x إذا كان `tan x = 0,3`.", "`x = tan^{-1}(0,3) ≈ 16,7°` أي حوالي 17°"]]}, {"n": 71, "m": 10, "i": "📐", "t": "حساب طول ضلع", "B": [["نعرف زاوية وضلعا", ["نختار النسبة التي تحتوي الضلع المعلوم والضلع المطلوب"]], ["المطلوب هو المقابل", ["نكتب `sin x = المقابل/الوتر` ونحل المعادلة"]], ["أمثلة", ["`BC = 2,5 ÷ sin 25° ≈ 5,92 cm`", "`RS = 3,5 × cos 37° ≈ 2,8 cm`"]], ["مثال بالظل", ["`FG = 4,5 × tan 53° ≈ 5,97 cm`"]]], "K": "اختر النسبة المناسبة، اكتب المعادلة، ثم أوجد المجهول بالضرب أو القسمة.", "M": ["أسمّي الأضلاع: مقابل ومجاور ووتر", "النسبة تضم معلوما ومجهولا فقط", "أقرّب في النهاية"], "X": "نبحث عن نسبة واحدة تربط الزاوية بالطول المعلوم والطول المطلوب، ثم نحل معادلة بسيطة.", "EX": [["مثلث ABC قائم في A، `AB = 2,5` والزاوية `C = 25°`. احسب BC.", "AB مقابل للزاوية C وBC وتر. `sin 25° = 2,5/BC`. `BC = 2,5/sin 25° ≈ 5,92 cm`"], ["مثلث RST قائم في T، `RT = 3,5` والزاوية `R = 37°`. احسب RS (الوتر).", "RT مجاور للزاوية R. `cos 37° = 3,5/RS`. `RS = 3,5/cos 37° ≈ 4,38 cm`"], ["مثلث قائم، زاويته 53° ومجاورها 4,5. احسب المقابل.", "`tan 53° = المقابل/4,5`. `المقابل = 4,5 × tan 53° ≈ 5,97`"]]}, {"n": 72, "m": 10, "i": "🎯", "t": "حساب قيس زاوية", "B": [["نعرف ضلعين", ["نكتب نسبة بين الضلعين المعلومين"]], ["بالجيب", ["`sin x = 2/5 = 0,4` فـ `x ≈ 23,6°`"]], ["بالظل", ["`tan x = 7/3` فـ `x ≈ 66,8°`"]], ["الإنشاء", ["نرسم مثلثا قائما أضلاعه 2 و5 (الوتر) فتظهر الزاوية x"]]], "K": "إذا عرفنا ضلعين: نكتب النسبة ثم نطبق sin⁻¹ أو cos⁻¹ أو tan⁻¹.", "M": ["أي نسبة تضم الضلعين المعطيين؟", "أقرّب إلى 0,1 درجة", "أتحقق أن الزاوية حادة"], "X": "الزاوية تُستخرج من النسبة بالدالة العكسية على الآلة الحاسبة.", "EX": [["مثلث قائم فيه المقابل 2 والوتر 5. جد الزاوية x.", "`sin x = 2/5 = 0,4`. `x = sin^{-1}(0,4) ≈ 23,6°`"], ["مثلث قائم فيه المقابل 7 والمجاور 3. جد الزاوية x.", "`tan x = 7/3`. `x = tan^{-1}(7/3) ≈ 66,8°`"]]}, {"n": 73, "m": 10, "i": "🔗", "t": "العلاقات بين sin وcos وtan", "B": [["العلاقة الأولى", ["`cos^{2} x + sin^{2} x = 1`"]], ["العلاقة الثانية", ["`tan x = sin x / cos x`"]], ["مثال", ["`cos x = 0,6`", "`sin^{2} x = 1 - 0,36 = 0,64` فـ `sin x = 0,8`"]], ["تتمة", ["`tan x = 0,8/0,6 = 4/3 ≈ 1,33`"]]], "K": "إذا عرفت cos تجد sin بالعلاقة الأولى، ثم tan بالقسمة.", "M": ["أستعمل sin وcos موجبين لأن الزاوية حادة", "أحسب المربع أولا ثم الجذر", "tan تُحسب في الأخير"], "X": "العلاقة الأولى هي فيثاغورس بعد القسمة على مربع الوتر.", "EX": [["`x` زاوية حادة و`cos x = 0,6`. احسب sin x وtan x.", "`sin^{2} x = 1-0,6^{2} = 0,64`. إذن `sin x = 0,8`. `tan x = 0,8/0,6 = 4/3 ≈ 1,33`"], ["`sin x = 0,8` و`x` حادة. احسب cos x.", "`cos^{2} x = 1-0,64 = 0,36`. إذن `cos x = 0,6`"]]}, {"n": 74, "m": 10, "i": "⭐", "t": "القيم الخاصة: 30° و45° و60°", "B": [["الزاوية 30°", ["`sin 30° = 1/2`", "`cos 30° = √3/2`", "`tan 30° = √3/3 ≈ 0,58`"]], ["الزاوية 60°", ["`sin 60° = √3/2`", "`cos 60° = 1/2`", "`tan 60° = √3 ≈ 1,73`"]], ["الزاوية 45°", ["`sin 45° = cos 45° = √2/2`", "`tan 45° = 1`"]], ["من أين؟", ["نصف مثلث متقايس الأضلاع (3 و3√3 و6) يعطي 30° و60°", "نصف مربع يعطي 45°"]]], "K": "نحفظ القيم: sin30=1/2، cos30=√3/2، tan30=√3/3، tan60=√3، sin45=cos45=√2/2، tan45=1.", "M": ["أتذكر sin30°=cos60°", "أستعمل القيم الدقيقة في الحسابات الدقيقة", "tan45°=1 لأن الضلعين متساويان"], "X": "هذه القيم تعطي نتائج دقيقة دون آلة حاسبة.", "EX": [["مثلث قائم فيه الوتر 6 وزاوية 30°. احسب المقابل والمجاور.", "المقابل: `6 × sin 30° = 6 × 1/2 = 3`. المجاور: `6 × cos 30° = 6 × √3/2 = 3√3 ≈ 5,2`"], ["تحقق أن `cos^{2} 30° + sin^{2} 30° = 1`.", "`(√3/2)^{2} + (1/2)^{2} = 3/4 + 1/4 = 1`"]]}, {"n": 75, "m": 11, "i": "➡️", "t": "الانسحاب والشعاع", "B": [["الانسحاب", ["تحويل ينقل كل نقطة بنفس الاتجاه والمنحى والطول"]], ["الشعاع", ["يعيّن بثلاثة عناصر: الاتجاه والمنحى والطول", "نرمز له `AB` (بداية A ونهاية B)"]], ["الصورة", ["صورة M بالانسحاب الذي يحوّل A إلى B هي M' حيث `MM' = AB`"]], ["خواص", ["يحافظ على الأطوال والزوايا والمساحات والتوازي"]]], "K": "الانسحاب يزحزح كل الشكل بشعاع واحد دون تغيير شكله أو حجمه.", "M": ["أرسم من M مستقيما يوازي (AB)", "أنقل الطول AB بنفس المنحى", "أتأكد أن MM' يساوي AB"], "X": "الشعاع سهم يعطي اتجاه الحركة ومنحاها ومقدارها.", "EX": [["كيف تنشئ صورة النقطة M بالانسحاب الذي يحوّل A إلى B؟", "نرسم من M مستقيما موازيا لـ (AB). نعيّن M' على هذا المستقيم بحيث `MM' = AB` وبنفس المنحى. فيكون ABM'M متوازي أضلاع عندما لا تكون M على (AB)"], ["صورة قطعة [MN] بانسحاب. ما طول صورتها إذا كان `MN = 4 cm`؟", "الانسحاب يحافظ على الأطوال. إذن الطول 4 cm"]]}, {"n": 76, "m": 11, "i": "🟰", "t": "تساوي شعاعين ومتوازي الأضلاع", "B": [["التساوي", ["`AB = CD` يعني نفس الاتجاه والمنحى والطول"]], ["متوازي الأضلاع", ["`AB = DC` ⇔ ABCD متوازي أضلاع", "الأشعة المتساوية تعطي أضلاعا متوازية متقايسة"]], ["المنتصف", ["`AI = IB` ⇔ I منتصف [AB]"]], ["ملاحظة", ["`AB = CD` ⇔ `AC = BD`"]]], "K": "AB = DC معناها ABCD متوازي أضلاع (ترتيب الرؤوس مهم).", "M": ["أنتبه لترتيب الحروف", "أرسم الشكل", "أستنتج التوازي والتساوي"], "X": "الشعاعان المتساويان يعطيان متوازي أضلاع، وهذا يختصر كثيرا من البراهين.", "EX": [["ABCD متوازي أضلاع. اكتب شعاعا يساوي `AB` وشعاعا يساوي `AD`.", "`AB = DC`. `AD = BC`"], ["`AI = IB`. ماذا تمثل I بالنسبة لـ [AB]؟", "I منتصف القطعة [AB]"]]}, {"n": 77, "m": 11, "i": "➕", "t": "مجموع شعاعين (علاقة شال)", "B": [["علاقة شال", ["`AB + BC = AC`", "نهاية الأول هي بداية الثاني"]], ["الشعاع المعدوم", ["`AB + BA = 0` لأن `AA` شعاع معدوم"]], ["قاعدة متوازي الأضلاع", ["`AB + AC = AD` ⇔ ABDC متوازي أضلاع"]], ["الشعاع المقابل", ["`BA = -AB`", "للشعاعين نفس الاتجاه والطول ومنحى معاكس"]]], "K": "AB + BC = AC دائما، وAB + AC = AD عندما يكون ABDC متوازي أضلاع.", "M": ["أرتب الأشعة بحيث تتتابع", "أبسّط باستعمال شال", "أنشئ المجموع بنقل شعاع"], "X": "جمع الأشعة هو تتابع حركتين: نبدأ من A ونصل إلى B ثم إلى C.", "EX": [["ABCD متوازي أضلاع. بسّط `AB + AD` و`AB + BC + CD`.", "`AB + AD = AC` (قاعدة متوازي الأضلاع). `AB + BC + CD = AC + CD = AD`"], ["بسّط: `AB + BC + CD + DA`.", "`AB+BC = AC` ثم `AC+CD = AD` ثم `AD+DA = 0`. فالمجموع الشعاع المعدوم"]]}, {"n": 78, "m": 11, "i": "🧩", "t": "براهين باستعمال الأشعة", "B": [["لإثبات متوازي أضلاع", ["نثبت `AB = DC` ثم نستنتج ABCD متوازي أضلاع"]], ["لإثبات منتصف", ["نثبت `AI = IB`"]], ["لإثبات توازي", ["إذا كان `AB = k CD` فالمستقيمان (AB) و(CD) متوازيان"]], ["لإثبات استقامة", ["إذا كان `AB = k AC` فالنقاط A وB وC على استقامة"]]], "K": "نحول المطلوب إلى تساوي أشعة ثم نستنتج الخاصية الهندسية.", "M": ["أكتب المطلوب بالأشعة", "أستعمل شال لتبسيط", "أستخلص النتيجة الهندسية"], "X": "الأشعة تحول الأشكال إلى جبر بسيط وتختصر الإثباتات الطويلة.", "EX": [["ABCD متوازي أضلاع. أثبت أن `AB + CD = 0`.", "ABCD متوازي أضلاع فـ `AB = DC`. و`CD = -DC`. إذن `CD = -AB` ومنه `AB + CD = 0`"], ["E نقطة تحقق `AE = AB + BC + CD`. ما موضع E؟", "بعلاقة شال: `AB + BC = AC` ثم `AC + CD = AD`. إذن `AE = AD` أي E = D"]]}, {"n": 79, "m": 12, "i": "🧭", "t": "مركبتا شعاع", "B": [["المعلم", ["معلم (O؛I؛J) يعطي محورين: الفواصل والتراتيب", "يكون متعامدا أو متجانسا أو عاديا"]], ["المركبتان", ["كل شعاع `u` له مركبتان `(x ; y)`"]], ["تساوي شعاعين", ["`u(x ; y) = v(x' ; y')` ⇔ `x = x'` و`y = y'`"]], ["جمع الأشعة", ["`u + v` مركبتاه `(x + x' ; y + y')`"]]], "K": "يتساوى شعاعان إذا تساوت مركبتاهما، ويُجمعان بجمع المركبات.", "M": ["أكتب الفاصلة قبل الترتيب", "المركبتان تقرآن من المعلم", "أتحقق بالتساوي مركبة بمركبة"], "X": "المركبتان هما عدد الوحدات أفقيا ثم عموديا لنصل من بداية الشعاع إلى نهايته.", "EX": [["`u(3 ; -2)` و`v(-1 ; 5)`. احسب مركبتي `u + v`